-- DeskAtlas: Operational and reference-data Realtime publication
-- Traceability: MS-35, SDD-C1, SDD-C3, SDD-C12, ERD-E1 through ERD-E14, QAD-TC35.
-- Generated by scripts/consolidate-supabase.py from archive/pre-consolidation.

BEGIN;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND tablename = 'reservations'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE reservations;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND tablename = 'payment_attempts'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE payment_attempts;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND tablename = 'workspace_instances'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE workspace_instances;
  END IF;
END $$;

DO $$
DECLARE
  table_name text;
BEGIN
  FOREACH table_name IN ARRAY ARRAY[
    'business_settings', 'operating_hours', 'payment_methods',
    'workspace_templates', 'floors', 'map_versions', 'workspace_instances'
  ]
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime'
        AND schemaname = 'public'
        AND tablename = table_name
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', table_name);
    END IF;
  END LOOP;
END $$;

COMMIT;
